import { test, expect } from '@playwright/test';

test.describe('Product Sorting Functionality', () => {
  test('should sort products by price in ascending order', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/');
    await page.login('standard_user', 'secret_sauce');
    await page.selectOption('#product_sort_container', 'lohi');
    await expect(page.locator('.inventory_item_price')).toBeVisible();
    await expect(page.locator('.inventory_item_price')).toHaveAttribute('data-test', 'inventory_item_price');
  });

  test('should not change the URL when sorting', async ({ page }) => {
    await page.goto('https://www.saucedemo.com/');
    await page.login('standard_user', 'secret_sauce');
    await page.selectOption('#product_sort_container', 'lohi');
    await expect(page).toHaveURL('https://www.saucedemo.com/');
  });
});
